const $=s=>document.querySelector(s), byId=id=>organs.find(o=>o.id===id);
const rootURL=new URL('.',import.meta.url), q=new URLSearchParams(location.search);
let scene,renderer,camera,modelRoot,anatomy,skeleton,raycaster,selected='heart',isolated=false,showSkeleton=true,showLabels=false,autoRotate=false,loaded=false,quiz=null,reviewedQuiz=null,hovered=null;
let lesson=null,lessonStep=0,physio=null,contextMode=false;
let fallbackMode=false,loadingTimer,demoStep=-1;
const demoSteps=[{title:'От целого к детали',hint:'Выберите орган на модели или в каталоге. Русское название, латынь и функция — рядом.'},{title:'Сравните лёгкие',hint:'Справа три доли, слева две. В 3D маршрут помогает рассмотреть форму.'},{title:'Найдите скрытое',hint:'Поджелудочная железа расположена позади желудка. В 3D сравните ракурсы.'},{title:'Один объём — два режима',hint:'Сравните 100 × 50 и 50 × 100. Одинаковый МОК не означает одинаковое состояние сердца.'},{title:'Проверьте понимание',hint:'Два вопроса, обратная связь и разбор. Это самопроверка, не клиническая оценка.'}];
const meshes=[], organMeshes=new Map(), centers=new Map(), labelNodes=new Map(), controllers=[],xrButtons=[];
let progress={viewed:[],best:{}};try{progress={...progress,...JSON.parse(localStorage.getItem('anatomia-progress-v1')||'{}')};if(!Array.isArray(progress.viewed))progress.viewed=[];if(!progress.best||typeof progress.best!=='object')progress.best={};}catch{}
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const view={theta:.13,phi:1.52,radius:1.88,target:new THREE.Vector3(0,1.26,0),toTarget:new THREE.Vector3(0,1.26,0),toRadius:1.88};
let xrInspectCenter=null,xrHover=-1,lastHover=0;const keyboardPoint={x:.5,y:.5};let toastTimer,prevTime=0,xrPanel,xrCanvas,xrCtx,xrTexture,xrActive=false,desktopState;
function save(){try{localStorage.setItem('anatomia-progress-v1',JSON.stringify(progress))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function setNav(id){document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-pressed',String(b.dataset.tab===id))})}
function renderList(){const focusId=document.activeElement?.dataset?.organ;const term=$('#search').value.trim().toLowerCase(),sys=$('#system').value;const filtered=organs.filter(o=>(sys==='all'||o.system===sys)&&`${o.name} ${o.latin}`.toLowerCase().includes(term));$('#organ-list').innerHTML=filtered.map(o=>`<button class="organ-item ${selected===o.id&&!quiz?'active':''}" style="--organ:${o.color}" data-organ="${o.id}" aria-pressed="${selected===o.id&&!quiz}" ${quiz?'disabled':''}><i class="dot"></i><span class="name">${o.name}<small>${o.latin}</small></span><span class="idx">${String(organs.indexOf(o)+1).padStart(2,'0')}</span></button>`).join('')||'<p class="empty">Орган не найден. Попробуйте другое название.</p>';$('#organ-list').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.organ,true));if(focusId)document.querySelector(`[data-organ="${focusId}"]`)?.focus({preventScroll:true})}
function renderCard(){
  updateFallback();
  if(quiz){renderQuiz();return}if(lesson){renderLesson();return}if(physio){renderPhysio();return}
  const focusId=document.activeElement?.id,o=byId(selected);
  document.body.classList.toggle('is-isolated',isolated);
  $('#organ-card').innerHTML=`<div class="card-kicker"><span>В ФОКУСЕ</span><div class="card-pager"><button id="organ-prev" aria-label="Предыдущий орган">‹</button><span class="number">${String(organs.indexOf(o)+1).padStart(2,'0')} / 16</span><button id="organ-next" aria-label="Следующий орган">›</button></div></div><h2>${o.name}</h2><div class="latin">${o.latin}</div><p class="brief">${briefs[o.id]}</p><div class="card-actions"><button class="primary" id="isolate">${icon(isolated?'layers':'focus')}${fallbackMode?'Выбрать другой орган':isolated?'Все органы':'Изолировать'}</button><button class="icon-button" id="focus" title="Приблизить" aria-label="Приблизить орган">${icon('search')}</button></div>${isolated&&!fallbackMode?`<button class="context-button" id="context" aria-pressed="${contextMode}">${icon('layers')}Соседние органы</button>`:''}<div class="card-links"><button class="text-button" id="organ-info">${icon('info')}Подробнее</button><button class="text-button" id="quick-quiz">Проверить себя ${icon('arrow')}</button></div>${reviewedQuiz?'<button class="secondary" id="back-results">← К результатам</button>':''}`;
  $('#isolate').onclick=()=>{if(fallbackMode){toggleCatalog(true);return}isolated=!isolated;contextMode=false;applyAppearance();if(isolated){focusOrgan();if(xrActive)xrFocusOrgan()}else home();renderCard();updateXRPanel()};
  $('#focus').onclick=()=>{if(fallbackMode){isolated=true;renderCard()}else focusOrgan()};$('#quick-quiz').onclick=()=>startQuiz('function',[o.id]);$('#organ-info').onclick=()=>organInfo(o.id);
  $('#organ-prev').onclick=()=>cycleOrgan(-1);$('#organ-next').onclick=()=>cycleOrgan(1);
  if(isolated&&!fallbackMode)$('#context').onclick=()=>{contextMode=!contextMode;applyAppearance();renderCard()};
  $('#back-results')?.addEventListener('click',restoreResults);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
}

function select(id,focus=false){
  if(!byId(id))return;if(quiz){if(quiz.type==='find'&&!quiz.answered&&!quiz.finished)answerFind(id);return}
  if(lesson||physio)clearStudyModes();selected=id;if(fallbackMode&&focus)isolated=true;const filter=$('#system');if(filter.value!=='all'&&byId(id).system!==filter.value)filter.value='all';
  if(xrActive&&isolated)xrFocusOrgan();if(!progress.viewed.includes(id)){progress.viewed.push(id);save()}
  renderList();renderCard();applyAppearance();if(fallbackMode)syncStagePrompt();if(focus)focusOrgan();updateXRPanel();
  if(focus){toggleCatalog(false);if(fallbackMode&&matchMedia('(max-width:700px)').matches)$('#detail').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}
}

function focusOrgan(){
  if(!loaded)return;if(xrActive){if(isolated)xrFocusOrgan();return}
  const c=centers.get(selected);if(!c)return;const box=new THREE.Box3();focusedIds().flatMap(id=>organMeshes.get(id)||[]).forEach(m=>box.expandByObject(m));
  view.toTarget.copy(box.getCenter(new THREE.Vector3()));view.toRadius=Math.max(.28,box.getSize(new THREE.Vector3()).length()*2.1*Math.max(1,1/(camera?.aspect||1)));
  if(!lesson)turnTo(.12,1.5);
}

function home(){
  if(xrActive){xrInspectCenter=null;modelRoot.rotation.set(0,0,0);modelRoot.scale.setScalar(1);modelRoot.position.set(0,0,-1.45)}
  view.toTarget.set(0,1.26,0);view.toRadius=1.88;turnTo(.13,1.52);isolated=false;contextMode=false;
  applyAppearance();if(!quiz)renderCard();$('#view-name').textContent='ВИД СПЕРЕДИ';
}

function applyAppearance(){
  updateFallback();if(!loaded||fallbackMode)return;const filter=$('#system').value,focus=focusedIds();
  const revealed=quiz?.answered&&!quiz.finished?(quiz.type==='case'?(current().targets||[current().target]):[current().id]):null;
  for(const [id,list]of organMeshes){const o=byId(id),ghost=isolated&&contextMode&&!focus.includes(id);list.forEach(m=>{
    m.visible=(!isolated||focus.includes(id)||contextMode)&&(!!quiz||!!lesson||filter==='all'||o.system===filter);
    const highlight=revealed?revealed.includes(id):id===selected&&!quiz;
    m.material.emissive.set(highlight?o.color:'#000000');m.material.emissiveIntensity=highlight?(revealed ? .3 : .13):0;
    if(m.material.transparent!==ghost){m.material.transparent=ghost;m.material.needsUpdate=true}
    m.material.opacity=ghost ? .075 : 1;m.material.depthWrite=!ghost;m.renderOrder=ghost?-1:0;
  })}
  if(skeleton)skeleton.visible=showSkeleton&&(!isolated||contextMode);
  $('#skeleton').setAttribute('aria-pressed',String(showSkeleton));$('#labels-toggle').setAttribute('aria-pressed',String(showLabels));$('#rotate').setAttribute('aria-pressed',String(autoRotate));
}

function showModal(html){$('#modal-content').innerHTML=html;const title=$('#modal-content h2');if(title){title.id='modal-title';$('#modal').setAttribute('aria-labelledby','modal-title')}$('#modal').showModal()}
function practice(){
  setNav('practice');showModal(`<div class="modal-eyebrow">ПРАКТИКА</div><h2>Попробуйте сами.</h2><div class="practice-grid"><button class="exercise" data-exercise="find" ${fallbackMode?'disabled title="Пространственный поиск требует WebGL 2"':''}>${icon('focus')}<b>Найти орган</b><small>${fallbackMode?'Нужен режим 3D':'8 заданий в 3D'}</small></button><button class="exercise" data-exercise="function">${icon('check')}<b>Проверить себя</b><small>8 коротких вопросов</small></button><button class="exercise accent" id="physiology">${icon('heart')}<b>Сердце в работе</b><small>Изменяйте. Сравнивайте.</small></button></div><h3>Увидеть связи${fallbackMode?' · доступны в 3D':''}</h3><div class="lesson-grid">${lessons.map(l=>`<button class="lesson-tile" data-lesson="${l.id}" ${fallbackMode?'disabled title="Визуальный маршрут требует режима 3D"':''}>${icon(l.icon)}<span><b>${l.name}</b><small>${l.hint}</small></span></button>`).join('')}</div><div class="practice-footer"><span>Изучено ${progress.viewed.length} / 16</span><button class="text-button" id="practice-reset">Начать заново</button><button class="text-button" data-exercise="case">4 ситуации →</button></div>`);
  document.querySelectorAll('[data-exercise]').forEach(b=>b.onclick=()=>{$('#modal').close();startQuiz(b.dataset.exercise)});
  document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(b.dataset.lesson));$('#physiology').onclick=physiology;$('#practice-reset').onclick=resetExperience;
}

function about(){setNav('sources');showModal(`<div class="modal-eyebrow">ОБ АТЛАСЕ / ВЕРСИЯ 1.2</div><h2>Анатомия, которую<br>можно рассмотреть.</h2><p>Учебный 3D-атлас для медицинского колледжа. 16 органов и групп структур, пространственный практикум, задания на функции и WebXR. Отбор структур предназначен для вводного изучения макроанатомии.</p><p><b>Как работать:</b> выберите орган в каталоге или на модели; вращайте перетаскиванием, приближайте колесом или щипком. Стрелки вращают вид, + / − меняют масштаб, H возвращает общий вид. После фокуса на сцене WASD перемещают прицел, Enter выбирает орган. Латеральность указана относительно тела. Скелет служит ориентиром; цвет органов условный.</p><p><b>VR:</b> откройте сайт по HTTPS в браузере совместимого шлема и нажмите «Войти в VR». Триггер выбирает орган или кнопку панели; стик вращает модель. Кнопки на панели: предыдущий / следующий орган, изоляция, поиск, выход. В шлеме доступен пространственный поиск; тесты с вариантами и расчётная модель доступны в обычном режиме. Доступность VR зависит от устройства и браузера.</p><p><b>Границы модели:</b> это образовательная визуализация, не диагностический инструмент и не тренажёр выполнения вмешательств. Не все отделы и микроструктуры представлены; размеры и расположение отражают исходную модель, а не варианты нормы у конкретного человека. Перед применением в оценивании содержание следует согласовать с преподавателем.</p><h3>Источники и лицензии</h3><ul class="source-list"><li>Геометрия: <a href="https://github.com/Z-Anatomy" target="_blank" rel="noopener">Z-Anatomy</a> / BodyParts3D, DBCLS; WebGL-экспорт: <a href="https://github.com/nqwrc/3d-anatomy" target="_blank" rel="noopener">nqwrc/3d-anatomy</a>. Компоненты имеют разные лицензии, в том числе модели почек — <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noopener">CC BY-NC 4.0</a> с некоммерческими условиями. Модели отобраны, объединены и оптимизированы; лицензии и авторство сохранены в <a href="./models/License.txt" target="_blank">исходном уведомлении</a> и <a href="./ASSET_SOURCES.md" target="_blank">описании источников</a>.</li><li>Учебные факты сверены с OpenStax, <i>Anatomy and Physiology 2e</i>, Betts et al. Ссылки на разделы приведены в каждой карточке. Формулировки карточек и задания составлены для этого атласа; изображения и задания учебника не копировались.</li><li>Рендеринг: <a href="https://threejs.org" target="_blank" rel="noopener">Three.js</a> (MIT). Ключи и аккаунты не требуются. Данные о пациентах не используются.</li></ul><button class="secondary" id="export">Скачать мой результат</button>`);$('#export').onclick=()=>{const b=new Blob([JSON.stringify({application:'ANATOMIA',version:'1.2',exported:new Date().toISOString(),...progress},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='anatomia-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function startQuiz(type,items){if(type==='find'&&(!loaded||fallbackMode)){toast('Пространственный поиск доступен после загрузки 3D. В резервном режиме работают вопросы и ситуации.');return}clearStudyModes();toggleCatalog(false);setSceneOnly(false);$('#modal').close();reviewedQuiz=null;quiz={type,items:items||(type==='find'?shuffle(organs.map(o=>o.id)).slice(0,8):type==='case'?cases:shuffle(organs.map(o=>o.id)).slice(0,8)),index:0,score:0,answered:false,last:null,custom:!!items,history:[],optionOrder:null};document.body.classList.add('in-practice');isolated=false;autoRotate=false;$('#system').value='all';$('#search').value='';setNav('practice');home();renderList();renderQuiz();updateXRPanel();if(type!=='find')focusQuestion();else focusScene()}
function current(){if(!quiz)return null;return quiz.type==='case'?quiz.items[quiz.index]:byId(quiz.items[quiz.index])}
function renderQuiz(){
  if(!quiz)return;updateFallback();document.body.classList.toggle('spatial-practice',quiz.type==='find');document.body.classList.toggle('quiz-finished',!!quiz.finished);syncStagePrompt();
  if(quiz.finished){const missed=quiz.history.filter(h=>!h.correct);$('#organ-card').innerHTML=`<div class="card-kicker"><span>ГОТОВО</span></div><h2 tabindex="-1" id="question-heading">${missed.length?'Повторим сложное?':'Всё верно.'}</h2><div class="score-ring" style="--score:${quiz.score/quiz.items.length*100}%"><div class="score">${quiz.score}<small>из ${quiz.items.length}</small></div></div>${[...new Set(missed.map(h=>h.organ))].map(id=>`<button class="secondary" data-review="${id}">${byId(id).name} ↗</button>`).join('')}${missed.length?'<button class="primary" id="retry-errors">Повторить ошибки</button>':''}<button class="${missed.length?'secondary':'primary'}" id="quiz-again">Ещё раз</button><button class="secondary" id="quiz-exit">В атлас</button>`;
    $('#quiz-again').onclick=()=>startQuiz(quiz.type,quiz.custom?[...quiz.items]:undefined);$('#retry-errors')?.addEventListener('click',()=>{const type=quiz.type,items=missed.map(h=>h.item);startQuiz(type,items)});
    document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const id=b.dataset.review;reviewedQuiz=quiz;exitQuiz();select(id);isolated=true;applyAppearance();focusOrgan();renderCard()});$('#quiz-exit').onclick=exitQuiz;return;
  }
  const o=current(),find=quiz.type==='find';if(!find&&!quiz.optionOrder)quiz.optionOrder=shuffle(o.options.map((_,i)=>i));
  $('#organ-card').innerHTML=`<div class="card-kicker"><span>${find?'НАЙДИТЕ В 3D':quiz.type==='case'?'СИТУАЦИЯ':'ПРОВЕРЬТЕ СЕБЯ'}</span><span class="number">${quiz.index+1} / ${quiz.items.length}</span></div><div class="quiz-progress"><i style="width:${(quiz.index+(quiz.answered?1:0))/quiz.items.length*100}%"></i></div><h2 tabindex="-1" id="question-heading">${find?o.name:quiz.type==='case'?o.title:'Что вы знаете?'}</h2>${find?'':`<p class="quiz-question">${o.question||o.text}</p><div id="answers">${quiz.optionOrder.map((i,n)=>`<button class="answer ${quiz.answered?(i===o.answer?'correct':i===quiz.last?'wrong':''):''}" data-answer="${i}" ${quiz.answered?'disabled':''}><span class="answer-key">${['A','B','C'][n]}</span>${o.options[i]}</button>`).join('')}</div>`}${quiz.answered?`<div class="feedback" role="status" tabindex="-1"><b>${quiz.correct?'Верно ✓':'Правильный ответ выделен'}</b><details><summary>Почему?</summary><p>${find?o.location:o.explain}</p></details></div><button class="primary" id="quiz-next">${quiz.index+1===quiz.items.length?'Результат':'Далее →'}</button><button class="text-button" id="inspect-answer">${fallbackMode?'Рассмотреть ответ ↗':'Рассмотреть в 3D ↗'}</button>`:''}<button class="secondary" id="quiz-exit">В атлас</button>`;
  document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerChoice(Number(b.dataset.answer)));if($('#quiz-next'))$('#quiz-next').onclick=nextQuestion;$('#inspect-answer')?.addEventListener('click',inspectAnswer);$('#quiz-exit').onclick=exitQuiz;
}

function recordAnswer(){const o=current();quiz.history.push({item:quiz.items[quiz.index],organ:quiz.type==='case'?o.target:o.id,correct:quiz.correct,answer:quiz.last})}
function inspectAnswer(){if(!quiz?.answered||quiz.finished)return;selected=quiz.type==='case'?current().target:current().id;isolated=true;applyAppearance();focusOrgan();if(!xrActive){$('.stage').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'});$('#viewport').focus({preventScroll:true})}updateXRPanel()}
function focusQuestion(){const h=$('#question-heading');if(h){h.focus({preventScroll:true});if(matchMedia('(max-width:820px)').matches)$('#detail').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}}
function syncStagePrompt(){
  const h=$('#scene-heading'),sub=$('#scene-subtitle'),controls=$('#stage-quiz');controls.innerHTML='';
  $('#scene-mode').textContent=fallbackMode?'РЕЗЕРВНЫЙ УЧЕБНЫЙ РЕЖИМ':lesson?'ВИЗУАЛЬНЫЙ МАРШРУТ':physio?'ФИЗИОЛОГИЯ':quiz?'ПРАКТИКА':'ИНТЕРАКТИВНЫЙ 3D-АТЛАС';
  if(lesson){h.textContent=lesson.name;sub.textContent=`Шаг ${lessonStep+1} / ${lesson.steps.length}`;return}
  if(physio){h.textContent='Сердце в работе';sub.textContent='Изменяйте частоту и объём';return}
  if(!quiz){h.textContent=fallbackMode?byId(selected).name:'Исследуйте тело.';sub.textContent=fallbackMode?'Статичный вид исходной модели':'Коснитесь органа или начните показ';return}
  h.textContent=quiz.finished?`Готово: ${quiz.score} / ${quiz.items.length}`:quiz.type==='find'?`Найдите: ${current().name}`:'Проверьте себя';
  sub.textContent=quiz.finished?'':quiz.type==='find'?(quiz.answered?(quiz.correct?'Верно ✓':`Ответ: ${current().name}`):'Коснитесь органа на модели'):`Вопрос ${quiz.index+1} / ${quiz.items.length}`;
  if(quiz.answered&&!quiz.finished){controls.innerHTML='<button id="stage-inspect">Показать</button><button id="stage-next">Далее →</button>';$('#stage-inspect').onclick=inspectAnswer;$('#stage-next').onclick=nextQuestion}
  else if(!quiz.finished&&quiz.type==='find'){controls.innerHTML='<button id="stage-exit">В атлас</button>';$('#stage-exit').onclick=exitQuiz}
  if(quiz.type==='find'&&!quiz.finished){const bar=document.createElement('div');bar.className='quiz-progress-mini';bar.setAttribute('aria-label',`Задание ${quiz.index+1} из ${quiz.items.length}`);bar.innerHTML=quiz.items.map((_,i)=>`<i class="${i<quiz.index?'done':i===quiz.index?'current':''}"></i>`).join('');controls.append(bar)}
}

function answerFind(id){if(!quiz||quiz.answered||quiz.finished||quiz.type!=='find')return;quiz.answered=true;quiz.last=id;quiz.correct=id===current().id;if(quiz.correct)quiz.score++;selected=current().id;recordAnswer();applyAppearance();renderQuiz();updateXRPanel();toast(quiz.correct?'Верно ✓':'Нужный орган выделен. Нажмите «Показать».');}
function answerChoice(index){if(!quiz||quiz.answered||quiz.finished)return;quiz.answered=true;quiz.last=index;quiz.correct=index===current().answer;if(quiz.correct)quiz.score++;selected=quiz.type==='case'?current().target:current().id;recordAnswer();applyAppearance();renderQuiz();$('.feedback')?.focus({preventScroll:true});updateXRPanel()}
function nextQuestion(){if(!quiz?.answered||quiz.finished)return;quiz.index++;if(quiz.index>=quiz.items.length){quiz.finished=true;if(!quiz.custom)progress.best[quiz.type]=Math.max(Number(progress.best[quiz.type])||0,quiz.score);progress.lastAttempt={type:quiz.type,score:quiz.score,total:quiz.items.length,date:new Date().toISOString(),answers:quiz.history};save();renderQuiz();focusQuestion();updateXRPanel();return}quiz.answered=false;quiz.last=null;quiz.optionOrder=null;home();renderQuiz();if(quiz.type!=='find')focusQuestion();else focusScene();updateXRPanel()}
function exitQuiz(){quiz=null;document.body.classList.remove('in-practice','spatial-practice','quiz-finished');isolated=false;setNav('atlas');renderList();renderCard();home();syncStagePrompt();updateXRPanel();$('#viewport').focus({preventScroll:true})}
function createLabels(){for(const o of organs){const d=document.createElement('div');d.className='label';d.textContent=o.name;$('#labels').append(d);labelNodes.set(o.id,d)}}
function updateLabels(){if(!camera)return;const w=$('#viewport').clientWidth,h=$('#viewport').clientHeight;let used=[];for(const o of organs){const d=labelNodes.get(o.id);const active=o.id===selected;const allowed=showLabels&&!quiz&&!xrActive&&(active||(!isolated&&['brain','lungR','liver','bladder'].includes(o.id)));const m=organMeshes.get(o.id)?.[0];if(!allowed||!m?.visible){d.hidden=true;continue}const pos=centers.get(o.id).clone();modelRoot.localToWorld(pos);const p=pos.project(camera);let x=(p.x*.5+.5)*w,y=(-p.y*.5+.5)*h;const left=o.id.endsWith('R')||o.id==='liver'||o.id==='brain';x+=left?-74:74;const clash=used.some(v=>Math.abs(v[1]-y)<30&&Math.abs(v[0]-x)<135);if(clash&&!active){d.hidden=true;continue}d.hidden=p.z>1||p.z<0||x<45||x>w-45||y<145||y>h-140;if(!d.hidden){used.push([x,y]);d.style.left=x+'px';d.style.top=y+'px';d.classList.toggle('active',active)}}}
function resize(){if(!renderer||!camera||xrActive||fallbackMode)return;const w=$('#viewport').clientWidth,h=$('#viewport').clientHeight;camera.aspect=w/h;camera.clearViewOffset();if(w>700)camera.setViewOffset(w,h,w*.08,0,w,h);camera.updateProjectionMatrix();renderer.setSize(w,h);}
function cameraUpdate(dt){if(xrActive)return;if(view.turn){const t=view.turn;t.time=Math.min(1,t.time+dt/0.9);const u=reduced?1:t.time*t.time*(3-2*t.time);view.theta=THREE.MathUtils.lerp(t.from,t.to,u);view.phi=THREE.MathUtils.lerp(t.fromPhi,t.toPhi,u);if(t.time>=1||reduced)view.turn=null;}view.target.lerp(view.toTarget,reduced?1:Math.min(1,dt*9));view.radius=THREE.MathUtils.lerp(view.radius,view.toRadius,reduced?1:Math.min(1,dt*9));if(autoRotate)view.theta+=dt*.15;const s=Math.sin(view.phi);camera.position.set(view.target.x+view.radius*s*Math.sin(view.theta),view.target.y+view.radius*Math.cos(view.phi),view.target.z+view.radius*s*Math.cos(view.theta));camera.lookAt(view.target);const theta=((view.theta%(Math.PI*2))+Math.PI*2)%(Math.PI*2);$('.left-marker').style.opacity=$('.right-marker').style.opacity=(theta<.35||theta>Math.PI*2-.35)?'.8':'0';$('#view-name').textContent=theta<.35||theta>Math.PI*2-.35?'ВИД СПЕРЕДИ':Math.abs(theta-Math.PI)<.35?'ВИД СЗАДИ':'СВОБОДНЫЙ ОБЗОР'}
